package com.gakbisa.backend.controller;
import com.gakbisa.backend.config.AppExceptions.ValidationException;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/sessions/{sessionId}/chat/{messageId}")
public class ChatModerationController {
 private final JdbcTemplate jdbc; public ChatModerationController(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private UUID room(UUID session){List<UUID> users=jdbc.query("SELECT b.requester_id,b.target_user_id FROM learning_sessions s JOIN barter_requests b ON b.id=s.barter_request_id WHERE s.id=?",(rs,n)->List.of((UUID)rs.getObject(1),(UUID)rs.getObject(2)),session).stream().findFirst().orElseThrow(()->new ValidationException("Sesi tidak ditemukan"));if(!users.contains(CurrentUser.id()))throw new ValidationException("Kamu bukan peserta sesi");String key=users.get(0).toString().compareTo(users.get(1).toString())<0?users.get(0)+":"+users.get(1):users.get(1)+":"+users.get(0);return jdbc.queryForObject("SELECT id FROM chat_rooms WHERE direct_key=?",UUID.class,key);}
 @DeleteMapping public Map<String,Object> delete(@PathVariable UUID sessionId,@PathVariable UUID messageId){UUID room=room(sessionId);int n=jdbc.update("UPDATE chat_messages SET deleted_at=now(),ciphertext=NULL,iv=NULL WHERE id=? AND room_id=? AND sender_id=? AND deleted_at IS NULL",messageId,room,CurrentUser.id());if(n==0)throw new ValidationException("Pesan tidak ditemukan atau bukan milikmu");return Map.of("deleted",true);}
 @PostMapping("/report") public Map<String,Object> report(@PathVariable UUID sessionId,@PathVariable UUID messageId,@RequestBody Body body){UUID room=room(sessionId);String reason=body.reason()==null?"":body.reason().trim();if(reason.length()<5||reason.length()>500)throw new ValidationException("Alasan laporan harus 5–500 karakter");Integer n=jdbc.queryForObject("SELECT count(*) FROM chat_messages WHERE id=? AND room_id=? AND sender_id<>? AND deleted_at IS NULL",Integer.class,messageId,room,CurrentUser.id());if(n==null||n==0)throw new ValidationException("Pesan tidak ditemukan atau tidak dapat dilaporkan");jdbc.update("INSERT INTO chat_message_reports(message_id,reporter_id,reason) VALUES (?,?,?) ON CONFLICT(message_id,reporter_id) DO NOTHING",messageId,CurrentUser.id(),reason);return Map.of("reported",true);}
 public record Body(String reason){}
}
